#include "stxlib/threads.hpp"
#include "stxlib/types.hpp"

namespace stxlib::detail::ic::threads {

// Thread::start: not_null(entry); else failure invalid_argument (no_entry).
[[nodiscard]] constexpr bool admits_start_entry(const ::stxlib::Thread::Entry entry) noexcept {
    const bool result = entry != nullptr;
    return result;
}

// Thread::start: stack_bytes in [minimum_thread_stack_bytes, maximum_thread_stack_bytes]; else failure invalid_argument
// (stack_size_out_of_range).
[[nodiscard]] constexpr bool admits_start_stack(const usize stack_bytes) noexcept {
    const bool result = ::stxlib::minimum_thread_stack_bytes <= stack_bytes
                     && stack_bytes <= ::stxlib::maximum_thread_stack_bytes;
    return result;
}

} // namespace stxlib::detail::ic::threads
